generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?depositTotal ?withdrawalTotal ?liquidityScore
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:hasPortfolioHealth ?ph .
  ?ph wm:liquidityScore ?liquidityScore .
  FILTER(xsd:decimal(?liquidityScore) < 30)

  {
    SELECT ?inv (SUM(?depAmt) AS ?depositTotal) (SUM(?withAmt) AS ?withdrawalTotal)
    WHERE {
      ?inv wm:hasCashFlow ?cf .
      ?cf wm:type ?cfType ;
          wm:amount ?amt .
      BIND(xsd:decimal(?amt) AS ?amtDec)
      BIND(LCASE(STR(?cfType)) AS ?typeLC)
      BIND(IF(?typeLC = "deposit", ?amtDec, 0) AS ?depAmt)
      BIND(IF(?typeLC = "withdrawal", ?amtDec, 0) AS ?withAmt)
    }
    GROUP BY ?inv
  }

  FILTER(?depositTotal < ?withdrawalTotal)
}
ORDER BY ?investorId

